 const pages={'/':home,'/predmety':subjectCatalog,'/ege':()=>examPage('ЕГЭ'),'/oge':()=>examPage('ОГЭ'),'/prepodavateli':teacherCatalog,'/ceny':prices,'/otzyvy-i-rezultaty':reviews,'/o-shkole':about,'/kontakty':contacts,'/chechenskiy-dlya-vzroslyh':adult,'/ege/matematika-baza':()=>subjectPage(1,'Базовая математика'),'/ege/matematika-profil':()=>subjectPage(1,'Профильная математика'),'/404':notFound};
 slugs.forEach((_,i)=>pages[subjectPath(i)]=()=>subjectPage(i));data.teachers.forEach((_,i)=>pages[teacherPath(i)]=()=>teacherProfile(i));['kabinet','politika','soglasie','cookies','oferta'].forEach(k=>pages['/'+k]=()=>service(k));
 const menu=document.getElementById('school-nav'),toggle=document.querySelector('.menu-toggle');
 const closeMenu=()=>{menu.classList.remove('open');toggle.setAttribute('aria-expanded','false');const more=menu.querySelector('details');if(more)more.open=false;};
 toggle.onclick=()=>{const expanded=toggle.getAttribute('aria-expanded')==='true';menu.classList.toggle('open',!expanded);toggle.setAttribute('aria-expanded',String(!expanded));};
 document.addEventListener('keydown',e=>{if(e.key==='Escape')closeMenu();});
 document.addEventListener('click',e=>{if(!e.target.closest('.school-header'))closeMenu();});
 document.querySelector('.skip-link').onclick=e=>{e.preventDefault();main.focus();};
