 function render(){let [path,query='']=location.hash.slice(1).split('?');path=path||'/';if(window.STATIC_SITE){if(location.hash.startsWith('#/')){const legacy=location.hash.slice(1),parts=legacy.split('?');location.replace(PAGES_BASE.slice(0,-1)+parts[0].replace(/\/?$/, '/')+(parts[1]?'?'+parts[1]:''));return;}path=location.pathname.slice(PAGES_BASE.length-1).replace(/\/index\.html$/, '/').replace(/\/$/,'')||'/';query=location.search.slice(1);}const params=new URLSearchParams(query);if(path==='/diagnostika'||path.startsWith('/diagnostika/')){location.replace('diagnostika.html#'+path.slice('/diagnostika'.length));return;}closeMenu();let html=path==='/zapis'?requestPage(params):(pages[path]||notFound)();if(window.STATIC_SITE)html=html.replace(/href="#(\/[^"]*)"/g,(_,url)=>{const [p,q]=url.split('?');return 'href="'+PAGES_BASE.slice(0,-1)+p.replace(/\/?$/,'/')+(q?'?'+q:'')+'"';});main.innerHTML=html;const heading=main.querySelector('h1');const title=(heading?.innerText||heading?.textContent||'XEXARXO').replace(/\s+/g,' ').trim();if(!window.STATIC_SITE){document.title=path==='/'?'XEXARXO — подготовка к ЕГЭ и ОГЭ в Грозном':title+' — XEXARXO';document.querySelector('meta[name=description]').content=path==='/'?'Подготовка к ЕГЭ и ОГЭ в Грозном и онлайн. Предметы, преподаватели и диагностики школы XEXARXO.':`${title}. Школа XEXARXO в Грозном: информация о подготовке, преподавателях и занятиях.`;}menu.querySelectorAll('a').forEach(a=>{const href=a.getAttribute('href');const match=window.STATIC_SITE?(href.replace(PAGES_BASE,'/').split('?')[0].replace(/\/$/,'')||'/'):href.slice(1);if(path===match||path.startsWith(match+'/'))a.setAttribute('aria-current','page');else a.removeAttribute('aria-current');});wire(params);window.scrollTo(0,0);main.focus({preventScroll:true});}
 window.addEventListener('hashchange',render);render();
